from dataclasses import dataclass
from typing import Optional

@dataclass(frozen=True)
class Ty:
    arg: Optional["Ty"] = None
    res: Optional["Ty"] = None
    @property
    def is_base(self) -> bool:
        return self.arg is None and self.res is None

def base() -> Ty:
    return Ty(None, None)

def arrow(a: Ty, b: Ty) -> Ty:
    return Ty(a, b)

def depth(t: Ty) -> int:
    if t.is_base:
        return 0
    return 1 + max(depth(t.arg), depth(t.res))

def size(t: Ty) -> int:
    if t.is_base:
        return 1
    return 1 + size(t.arg) + size(t.res)

def tsb(t: Ty) -> int:
    if t.is_base:
        return 1
    return (tsb(t.arg) + 1) * (tsb(t.res) + 1)

def chain(d: int) -> Ty:
    t = base()
    for _ in range(d):
        t = arrow(base(), t)
    return t

def bushy(n: int) -> Ty:
    t = base()
    for _ in range(n):
        t = arrow(t, t)
    return t

def demo_chain_singly_exponential(max_d: int = 10) -> None:
    """Chains: tsb stays under 3^(depth+1); closed form 3*2^d - 2."""
    for d in range(max_d + 1):
        t = chain(d)
        assert tsb(t) <= 3 ** (depth(t) + 1)
        assert tsb(t) == 3 * 2 ** d - 2
        print(f"depth={d:2d}  tsb={tsb(t):8d}  <= 3^(d+1)={3**(d+1):8d}")

if __name__ == "__main__":
    demo_chain_singly_exponential()

